  aspect-ratio: 3 / 2;
  overflow: hidden;
  background: #e5e7eb;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.product-card:hover .product-image img {
