}

.badge-sale {
  background: #dc2626;
}

/* Info */
.product-info {
  display: flex;
  flex-direction: column;
  flex: 1; /* fills remaining height so footers align */
  padding: 1.25rem;
}

.product-category {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
  margin-bottom: 0.25rem;
}

.product-title {
