  margin-bottom: 0.5rem;
}

.product-description {
  font-size: 0.9rem;
  color: #4b5563;
  margin-bottom: 1.25rem;
}

/* Footer: pinned to the bottom of the card */
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: auto;
}

.product-price {
