  background-color: #f4f5f7;
  color: #222;
  line-height: 1.5;
}

img {
  display: block;
  max-width: 100%;
}

/* ---------- Layout ---------- */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.section-title {
  font-size: 2rem;
  margin-bottom: 1.5rem;
  text-align: center;
}

/* ---------- Grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr); /* Desktop: 3 per row */
  gap: 1.5rem;
}

/* ---------- Card ---------- */
.product-card {
  display: flex;
  flex-direction: column;
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
}

/* Image */
.product-image {
  position: relative;
  aspect-ratio: 3 / 2;
  overflow: hidden;
}

.product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.product-card:hover .product-image img {
  transform: scale(1.05);
}

.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background: #2563eb;
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.badge-sale {
  background: #dc2626;
}

/* Info */
.product-info {
  display: flex;
  flex-direction: column;
  flex: 1; /* Makes all cards in a row equal height */
  padding: 1.25rem;
}

.product-category {
  font-size: 0.8rem;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 0.25rem;
}

.product-title {
  font-size: 1.15rem;
  margin-bottom: 0.5rem;
}

.product-description {
  font-size: 0.95rem;
  color: #4b5563;
  margin-bottom: 1rem;
  flex: 1; /* Pushes footer to bottom */
}

/* Footer */
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.product-price {
  font-size: 1.25rem;
  font-weight: 700;
  color: #111;
}

.old-price {
  font-size: 0.9rem;
  font-weight: 400;
  color: #9ca3af;
  margin-left: 0.25rem;
}

.btn {
  background: #111827;
  color: #fff;
  border: none;
  padding: 0.6rem 1.1rem;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s ease;
}

.btn:hover {
  background: #2563eb;
}

.btn:focus-visible {
  outline: 3px solid #93c5fd;
  outline-offset: 2px;
}

/* ---------- Responsive ---------- */

/* Tablet: 2 per row */
@media (max-width: 900px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Mobile: 1 per row */
@media (max-width: 600px) {
  .product-grid {
    grid-template-columns: 1fr;
  }

  .section-title {
    font-size: 1.5rem;
  }
}
```

## How it works

| Screen width | Columns | Rule |
|---|---|---|
| > 900px (desktop) | 3 | `repeat(3, 1fr)` |
| 601–900px (tablet) | 2 | `repeat(2, 1fr)` |
| ≤ 600px (mobile) | 1 | `1fr` |

**Key techniques:**
- **CSS Grid** with `fr` units splits the space evenly, and `gap` handles spacing without margin hacks.
- **Equal-height cards:** Grid stretches cards in a row to the same height, and `flex: 1` on the description pushes the price and button to the bottom.
- **Consistent images:** `aspect-ratio: 3 / 2` with `object-fit: cover` keeps images uniform regardless of source dimensions.
- **Accessibility:** semantic `<article>` elements, `alt` text, and a visible `:focus-visible` outline for keyboard users.

If you want exactly two breakpoints (no tablet step), just delete the `900px` media query.

