/* ---------- Header / Footer ---------- */
.site-header {
  text-align: center;
  padding: 3rem 1rem 2rem;
}

.site-header h1 {
  margin: 0;
  font-size: clamp(2rem, 5vw, 3rem);
  letter-spacing: -0.02em;
