  margin: 0.5rem 0 0;
  color: #666;
}

.site-footer {
  text-align: center;
  padding: 2rem 1rem;
  color: #888;
  font-size: 0.9rem;
}

/* ---------- Gallery Grid ---------- */
.gallery {
  list-style: none;
  margin: 0 auto;
  padding: 0 1rem;
  max-width: 1200px;
  display: grid;
  /* Equal-width columns that wrap responsively */
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1rem;
}

/* ---------- Thumbnails ---------- */
.thumb {
  position: relative;
  display: block;
  aspect-ratio: 1 / 1;      /* Every thumbnail is a perfect square */
  overflow: hidden;
  border-radius: 10px;
  background: #ddd;          /* Placeholder while loading */
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;         /* Crop to fill, no distortion */
  display: block;
  transition: transform 0.4s ease;
}

.thumb:hover,
.thumb:focus-visible {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
}

.thumb:hover img,
.thumb:focus-visible img {
  transform: scale(1.06);
}

.thumb:focus-visible {
  outline: 3px solid #4a7dff;
  outline-offset: 3px;
}

/* ---------- Captions ---------- */
.caption {
  position: absolute;
  inset: auto 0 0 0;
  padding: 2rem 0.75rem 0.75rem;
  color: #fff;
  font-weight: 600;
  font-size: 0.95rem;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.thumb:hover .caption,
.thumb:focus-visible .caption {
  opacity: 1;
  transform: translateY(0);
}

/* Always show captions on touch devices (no hover) */
@media (hover: none) {
  .caption {
    opacity: 1;
    transform: none;
  }
}

/* ---------- Lightbox ---------- */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  background: rgba(0, 0, 0, 0.9);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.lightbox:target {
  opacity: 1;
  visibility: visible;
}

.lightbox img {
  max-width: 100%;
  max-height: 90vh;
  border-radius: 6px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
}

.lightbox .close {
  position: absolute;
  top: 1rem;
  right: 1.5rem;
  color: #fff;
  font-size: 2.5rem;
  line-height: 1;
  text-decoration: none;
  opacity: 0.8;
}

.lightbox .close:hover {
  opacity: 1;
}

/* ---------- Small screens ---------- */
@media (max-width: 480px) {
  .gallery {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.5rem;
  }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}
