  transition: opacity 0.25s ease, transform 0.25s ease;
}

.gallery-item a:hover .caption,
.gallery-item a:focus-visible .caption {
  opacity: 1;
  transform: translateY(0);
}

/* Always show captions on touch devices (no hover) */
@media (hover: none) {
  .caption {
    opacity: 1;
    transform: none;
  }
}

/* ---------- Lightbox ---------- */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  background: rgba(0, 0, 0, 0.85);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
  cursor: zoom-out;
}

