  padding-left: 28px;
  margin-bottom: 12px;
}

.card__features li::before {
  content: "✓";
  position: absolute;
  left: 0;
  top: 0;
  color: var(--color-primary);
  font-weight: 700;
}

/* ---------- Button ---------- */
.card__button {
  display: block;
  text-align: center;
  padding: 14px 20px;
  border-radius: 10px;
  font-weight: 600;
  text-decoration: none;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
  transition: background 0.2s ease, color 0.2s ease;
}

.card__button:hover,
.card__button:focus-visible {
  background: var(--color-primary);
  color: #fff;
}

.card__button:focus-visible {
  outline: 3px solid rgba(79, 70, 229, 0.4);
  outline-offset: 2px;
}

/* ---------- Featured card ---------- */
.card--featured {
  border: 2px solid var(--color-primary);
  box-shadow: 0 16px 32px rgba(79, 70, 229, 0.15);
  transform: scale(1.04);
}

.card--featured:hover {
  transform: scale(1.04) translateY(-4px);
}

.card--featured .card__button {
  background: var(--color-primary);
  color: #fff;
}

.card--featured .card__button:hover {
  background: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
}

.card__badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: #fff;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 999px;
  white-space: nowrap;
}

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .pricing__grid {
    grid-template-columns: 1fr;
    max-width: 420px;
    margin: 0 auto;
  }

  .card--featured,
  .card--featured:hover {
    transform: none;
  }
}
```

## Key features

- **CSS Grid layout**: three equal columns that stack into one column on screens under 900px.
- **Equal-height cards**: `flex-grow: 1` on the feature list pushes all buttons to the bottom, so they align even when cards have different numbers of features.
- **Highlighted middle plan**: the Pro card has a colored border, a slight scale-up, a "Most popular" badge, and a filled button.
