<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Responsive Product Grid</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>

  <section class="product-grid">
    <!-- Product Card 1 -->
    <article class="product-card">
      <img src="https://via.placeholder.com/400x300" alt="Wireless Headphones" class="product-image">
      <div class="product-info">
        <h2 class="product-title">Wireless Headphones</h2>
        <p class="product-description">Noise-cancelling over-ear headphones with 30-hour battery life.</p>
        <div class="product-footer">
          <span class="product-price">$149.99</span>
          <button class="add-to-cart">Add to Cart</button>
        </div>
      </div>
