  font-size: 1.5rem;
  font-weight: 600;
  margin-right: 0.15rem;
}

.price .period {
  font-size: 1rem;
  font-weight: 500;
  color: #64748b;
  margin-left: 0.25rem;
}

/* Features List */
.features {
