  color: #334155;
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
}

.features li::before {
  content: "✓";
  color: #4f46e5;
  font-weight: bold;
  margin-right: 0.75rem;
}

/* Buttons */
.btn {
  display: block;
  width: 100%;
  text-align: center;
  padding: 0.85rem 1.5rem;
