      margin: 0;                 /* reset <figure> default margin */
      aspect-ratio: 1 / 1;       /* ← forces a perfect square box */
      overflow: hidden;
      border-radius: var(--radius);
      background: #e3e5e9;       /* placeholder while image loads */
      box-shadow: var(--shadow-sm);
      transition: transform .3s var(--ease),
                  box-shadow .3s var(--ease);
    }

    .thumb img {
      display: block;
      width: 100%;
      height: 100%;
      /* ← the key trick: fill the square, crop the overflow.
         Works no matter what the source image's aspect ratio is. */
      object-fit: cover;
      object-position: center;
      transition: transform .5s var(--ease);
    }

    /* ---------- Hover / focus effects ---------- */
    .thumb:hover,
    .thumb:focus-within {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .thumb:hover img,
    .thumb:focus-within img {
      transform: scale(1.07);
    }

    /* ---------- Caption overlay ---------- */
    .thumb figcaption {
      position: absolute;
      inset: auto 0 0 0;
      padding: 2.5rem .85rem .8rem;
      font-size: .82rem;
      font-weight: 500;
      color: #fff;
      background: linear-gradient(to top,
