                  transparent 100%);
      opacity: 0;
      transform: translateY(10px);
      transition: opacity .3s var(--ease), transform .3s var(--ease);
      pointer-events: none;
    }

    .thumb:hover figcaption,
    .thumb:focus-within figcaption {
      opacity: 1;
      transform: translateY(0);
    }

