      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0;
      list-style: none;
    }

    /* ---------- Thumbnail (uniform size) ---------- */
    .gallery__item {
      position: relative;
      aspect-ratio: 1 / 1;        /* every tile is a perfect square */
      overflow: hidden;
      border-radius: var(--radius);
      background: var(--surface);
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
      isolation: isolate;
    }

    .gallery__link {
      position: absolute;
      inset: 0;
      display: block;
      color: inherit;
      text-decoration: none;
      border-radius: inherit;
    }

    /* Images fill the square and crop instead of distorting */
    .gallery__img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
      object-position: center;
      transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
      will-change: transform;
    }

    /* Dark gradient revealed on hover/focus */
    .gallery__link::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(
        to top,
        rgba(0, 0, 0, 0.78) 0%,
        rgba(0, 0, 0, 0.35) 40%,
        rgba(0, 0, 0, 0) 65%
