      width: 100%;
      height: 100%;
      /* The key to even sizing: crop instead of distort */
      object-fit: cover;
      object-position: center;
      transition: transform 0.45s cubic-bezier(0.2, 0.7, 0.3, 1);
    }

    /* ---------- Caption overlay ---------- */
    .thumb figcaption {
      position: absolute;
