  --shadow: 0 1px 2px rgba(16, 24, 40, .06),
            0 8px 24px rgba(16, 24, 40, .08);
}

*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  padding: clamp(1rem, 4vw, 3rem);
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
}

/* ---------- Page ---------- */
.products {
  max-width: 1200px;
  margin-inline: auto;
}

.products__title {
  margin: 0 0 1.5rem;
  font-size: clamp(1.5rem, 3vw, 2rem);
}

/* ---------- The grid ---------- */
.product-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--gap);
  /* minmax(0, 1fr) prevents long content from blowing out the track */
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* Tablet: 2 per row */
@media (max-width: 900px) {
  .product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Mobile: 1 per row */
@media (max-width: 600px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
}

/* ---------- Card ---------- */
.product-card > article {
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 1px solid #e8e9ec;
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform .2s ease, box-shadow .2s ease;
}

.product-card:hover > article {
  transform: translateY(-4px);
  box-shadow: 0 2px 4px rgba(16, 24, 40, .08),
              0 16px 32px rgba(16, 24, 40, .12);
}

.product-card__media {
  position: relative;
  aspect-ratio: 4 / 3;          /* keeps every image the same height */
  background: #eceef1;
}

.product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.product-card__badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .02em;
  color: #fff;
  background: var(--accent);
  border-radius: 999px;
}

.product-card__body {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  padding: 1rem 1.1rem 1.2rem;
  flex: 1;
}

.product-card__title {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.35;
}

.product-card__title a {
  color: inherit;
  text-decoration: none;
}

.product-card__title a:hover { text-decoration: underline; }

.product-card__desc {
  margin: 0;
  color: var(--muted);
  font-size: .9rem;
}

.product-card__price {
  margin: .25rem 0 0;
  font-size: 1.1rem;
  font-weight: 700;
}

.product-card__price s {
  color: var(--muted);
  font-weight: 400;
  font-size: .95rem;
}

.product-card__cta {
  margin-top: auto;              /* pins button to the bottom of every card */
  align-self: flex-start;
  padding: .6rem 1.1rem;
  font: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: 0;
  border-radius: 8px;
  cursor: pointer;
  transition: background .15s ease;
}

.product-card__cta:hover { background: #2559c9; }

:where(a, button):focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- Utility ---------- */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  margin: -1px; padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
```

### Key notes

- **`minmax(0, 1fr)`** instead of `1fr` — prevents long words or oversized images from expanding a track and breaking the row.
- **`aspect-ratio: 4 / 3` + `object-fit: cover`** — every image is cropped to the same box, so card heights stay aligned regardless of source image dimensions.
- **`margin-top: auto` on the button** — pushes the CTA to the bottom so buttons line up across a row even when descriptions differ in length.
- **Breakpoints at 900px / 600px** — adjust these to match your design; the tablet rule is optional if you want a straight 3 → 1 jump.

### Alternative: fully fluid grid (no media queries)

If you'd rather let the layout respond to available space automatically:

```css
.product-grid {
  display: grid;
  gap: var(--gap);
  grid-template-columns: repeat(auto-fit, minmax(min(280px, 100%), 1fr));
}
```

This yields 3 columns on a ~1200px container, 2 around 600–900px, and 1 on phones — with a single rule and no breakpoints. The tradeoff is that the column count depends on container width rather than device width, so it can land on 2 columns on some tablets.

