  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* The key to evenly sized thumbnails:
   a fixed aspect-ratio box + object-fit: cover */
.gallery__item img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;      /* change to 1 / 1 for squares */
  object-fit: cover;         /* crop instead of stretching */
  transition: transform 0.4s ease;
}

.gallery__item figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 2rem 0.9rem 0.8rem;
  font-size: 0.9rem;
  font-weight: 500;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.85), transparent);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

/* ---------- Hover effects ---------- */
.gallery__item:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 26px rgba(0, 0, 0, 0.5);
}

.gallery__item:hover img {
  transform: scale(1.06);
}

.gallery__item:hover figcaption {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Responsive tweaks ---------- */
@media (max-width: 640px) {
  .gallery {
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 0.75rem;
  }

  .gallery__item figcaption {
    opacity: 1;
    transform: none;
    position: static;
    padding: 0.6rem 0.75rem;
    background: #1e2129;
  }
}
```

## How the even sizing works

| Technique | Purpose |
|---|---|
| `display: grid` with `repeat(auto-fill, minmax(240px, 1fr))` | Creates equal-width columns that reflow responsively |
| `aspect-ratio: 4 / 3` on the `<img>` | Locks every thumbnail to the same height, even for portrait or panorama source images |
| `object-fit: cover` | Crops the image to fill the box without distortion |
| `width: 100%` + `display: block` | Stretches the image to the column width and removes the inline gap under it |

**To make square thumbnails**, change `aspect-ratio: 4 / 3;` to `aspect-ratio: 1 / 1;`.

