    </figure>

    <figure class="gallery__item">
      <img src="https://picsum.photos/seed/lake/800/600" alt="Calm lake reflection" loading="lazy">
      <figcaption>Still Waters</figcaption>
    </figure>

    <figure class="gallery__item">
      <img src="https://picsum.photos/seed/meadow/800/600" alt="Green meadow" loading="lazy">
      <figcaption>Green Meadow</figcaption>
    </figure>

    <figure class="gallery__item">
      <img src="https://picsum.photos/seed/coast/800/600" alt="Rocky coastline" loading="lazy">
      <figcaption>Rocky Coast</figcaption>
    </figure>
  </main>

  <!-- Simple lightbox -->
