  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-radius: 999px;
  white-space: nowrap;
}

.card__name {
  margin: 0 0 6px;
  font-size: 1.25rem;
  font-weight: 600;
}

.card__description {
  margin: 0 0 20px;
  color: #64748b;
  font-size: 0.95rem;
}

/* ---------- Price ---------- */
.card__price {
  margin: 0 0 24px;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 2px;
}

.card__currency {
  font-size: 1.25rem;
  font-weight: 600;
  align-self: flex-start;
  margin-top: 8px;
}

.card__amount {
  font-size: 3rem;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
}

.card__period {
  color: #64748b;
  font-size: 0.95rem;
}

/* ---------- Features ---------- */
.card__features {
  list-style: none;
  margin: 0 0 28px;
  padding: 0;
  text-align: left;
  display: grid;
  gap: 12px;
  flex: 1;
}

.card__feature {
  position: relative;
  padding-left: 28px;
  font-size: 0.95rem;
}

.card__feature::before {
  content: "✓";
  position: absolute;
  left: 0;
  top: 0;
  color: #10b981;
  font-weight: 700;
}

.card__feature--muted {
  color: #94a3b8;
}

.card__feature--muted::before {
  content: "—";
  color: #cbd5e1;
}

/* ---------- Buttons ---------- */
.btn {
  display: block;
  padding: 12px 20px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.95rem;
